const raw = $json.content;
if (!raw) throw new Error('No content field: ' + JSON.stringify($json));
const data = JSON.parse(raw);
return { json: data };

const ef = $node["Edit Fields"].json;
const job = $node["Parse Job"].json;

const language = String(ef.language || job.language || 'nb').trim();
const siteLanguage = String(ef.site_language || job.site_language || 'no').trim();
const market = String(ef.market || job.market || 'no').trim();

function chooseScriptLanguage(languageValue, siteValue, marketValue) {
  const lang = String(languageValue || '').trim().toLowerCase().replace('_', '-');
  const site = String(siteValue || '').trim().toLowerCase().replace('_', '-');
  const market = String(marketValue || '').trim().toLowerCase();

  if (lang === 'nn' || lang === 'nynorsk' || site === 'nn' || site === 'nn-no') return 'nn';
  if (lang === 'sv' || lang === 'se' || lang === 'sv-se' || lang === 'swedish' || lang === 'svensk' || lang === 'svenska' || site === 'sv' || site === 'sv-se' || site === 'se' || ['se', 'swe', 'sweden', 'sverige'].includes(market)) return 'sv';
  if (lang === 'nb' || lang === 'no' || lang === 'bokmal' || lang === 'bokm?l' || lang === 'bokm?l' || site === 'nb-no' || site === 'no') return 'nb';
  if (lang === 'en-gb' || lang === 'en-uk' || site === 'en-gb' || site === 'en-uk' || ['gb', 'uk'].includes(market)) return 'en-GB';
  if (lang === 'en-us' || site === 'en-us' || ['us', 'usa'].includes(market)) return 'en-US';
  if (lang === 'en') return ['gb', 'uk'].includes(market) || site === 'en-gb' ? 'en-GB' : 'en-US';
  return 'nb';
}

const scriptLanguage = chooseScriptLanguage(language, siteLanguage, market);

// Title -> base folder slug. Lookup is case-insensitive on the title.
// Includes Norwegian titles and English printed titles. Language variants now
// share the same book folder/assets/Qwen headswap workflow; only textScript
// changes per language.
