const HANDLE_TO_SLUG = {
  "enhjorningsdalen":         "enhjorning",
  "fotball-vm": "fotball-vm",
  "fotballvm": "fotball-vm",
  "vm-i-fotball": "fotball-vm",
  "world-cup": "fotball-vm",
  "the-world-cup": "fotball-vm",
  "football-world-cup": "fotball-vm",
  "soccer-world-cup": "fotball-vm",
  "fotbolls-vm": "fotball-vm",
  "the-secret-of-the-kingdom": "kongerikets-hemmelighet",
  "kungarikets-hemlighet": "kongerikets-hemmelighet",
  "tapte-superbyen": "den-tapte-superbyen",
  "the-lost-super-city": "den-tapte-superbyen",
  "forsvunne-dinosauregget": "det-forsvunne-dinosauregget",
  "the-lost-dinosaur-egg": "det-forsvunne-dinosauregget",
  "den-magiske-reisen":       "den-magiske-reisen-gutt",
  "den-magiske-reisen-jente": "den-magiske-reisen-jente"
};

const GENDERED_TITLES = new Set(["den magiske reisen", "magic journey", "the magic journey", "magiska resan", "den magiska resan"]);

const titleKey = String(ef.book_title || '').trim().toLowerCase();
const genderKey = String(job.gender || '').trim().toLowerCase();

function resolveGendered() {
  if (genderKey === 'girl' || genderKey === 'jente' || genderKey === 'flicka' || genderKey === 'tjej') return 'den-magiske-reisen-jente';
  if (genderKey === 'boy' || genderKey === 'gutt' || genderKey === 'pojke' || genderKey === 'kille') return 'den-magiske-reisen-gutt';
  throw new Error('Cannot resolve den-magiske-reisen variant - missing or unknown gender: ' + JSON.stringify(job.gender));
}

let slug;
const handle = String(ef.book_slug || '').trim().toLowerCase();
if (handle) {
  if (handle === 'den-magiske-reisen' || handle === 'den-magiske-reisen-jente') {
    slug = resolveGendered();
  } else {
    slug = HANDLE_TO_SLUG[handle] || handle;
  }
}

if (!slug && GENDERED_TITLES.has(titleKey)) slug = resolveGendered();
if (!slug) slug = TITLE_TO_SLUG[titleKey];

if (!slug && titleKey) {
  slug = titleKey
    .replace(/\s+/g, '-')
    .replace(/[^a-z0-9-]/g, '')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');
}

if (!slug) throw new Error('Cannot resolve slug. book_title=' + ef.book_title + ' book_slug=' + ef.book_slug);

return { json: {
  order_id:        ef.order_id,
  book_slug:       slug,
  child_name:      ef.child_name,
  face_image:      ef.face_image,
  cover_type:      ef.cover_type,
  shipping:        ef.shipping,
  customer:        ef.customer,
  book_title:      ef.book_title,
  language:        language || 'nb',
  site_language:   siteLanguage || 'no',
  market:          market || 'no',
  script_language: scriptLanguage,
  continue_code: ef.continue_code || '',
  continue_url: ef.continue_url || '',
  continue_coupon: ef.continue_coupon || '',
  continue_callback: ef.continue_callback || '',
  next_book_id: ef.next_book_id || '',
  next_book_slug: ef.next_book_slug || '',
  next_book_title: ef.next_book_title || '',
} };

const inp = $input.first().json;
const config = inp.config;
if (!config) throw new Error('Pages Config did not receive config');

const workflowFile = config.workflowApi ||
  (config.workflowApis && (config.workflowApis.default || config.workflowApis.innerpages || config.workflowApis.frontpage)) ||
  'workflow_api.json';
const patchNodes = config.patchNodes || config.innerPatchNodes || { template: '95', face: '10', output: '81' };

if (!patchNodes || !patchNodes.template || !patchNodes.face || !patchNodes.output) {
  throw new Error('Missing Qwen headswap patchNodes in config for book ' + (inp.book_slug || 'unknown'));
}

// --- Uttrykksvarianter av barnebildet ----------------------------------------
// build_face_variants.py har lagt <order_id>-<uttrykk>.jpg i C:/ComfyUI/input.
// Mangler filen (scriptet feilet, eller en gammel ordre kjores om), brukes
// originalbildet - en side skal aldri feile fordi et uttrykk mangler.
const fsExpr = require('fs');
const FACE_EXPRESSIONS = ['noytral', 'smil', 'trist'];
const faceBase = String(inp.faceFilename || '');
const faceStem = faceBase.replace(/\.[^.]+$/, '');
function faceFor(expression) {
  const expr = String(expression || 'noytral');
  if (!faceStem || FACE_EXPRESSIONS.indexOf(expr) === -1) return faceBase;
  const candidate = faceStem + '-' + expr + '.jpg';
  try {
    if (fsExpr.existsSync('C:/ComfyUI/input/' + candidate)) return candidate;
  } catch (error) {}
  console.warn('[FACE] mangler ' + candidate + ' - bruker ' + faceBase);
  return faceBase;
}

const items = config.pages.map(function(p) {
  return { json: {
    page_key:          p.page_key,
    template_image:    p.template_image,
    mask_image:        p.mask_image,
    face_image:        faceFor(p.face_expression),
    output_dir:        inp.outputDir,
    order_id:          inp.order_id,
    book_slug:         inp.book_slug,
    child_name:        inp.child_name,
    cover_type:        inp.cover_type,
    shipping:          inp.shipping,
    customer:          inp.customer,
    book_title:        inp.book_title,
    language:          inp.language || 'nb',
    site_language:     inp.site_language || 'no',
    market:            inp.market || 'no',
    script_language:   inp.script_language || 'nb',
    config:            config,
    orderPath:         inp.orderPath,
    workflow_role:     'page',
    workflow_api_file: workflowFile,
    patchNodes:        patchNodes,
  }};
});

// --- Fortsett eventyret: ekstra render av neste bok sin forside ---------------
// Ett ekstra element i Pages Config arver hele Page Loop-maskineriet
// (dispatch, polling, timeout, retry). Uten continue_code skjer ingenting.
const contCode = String(inp.continue_code || '').trim();
const nextSlug = String(inp.next_book_slug || '').trim();
if (contCode && nextSlug && nextSlug !== String(inp.book_slug || '')) {
  try {
    const fs = require('fs');
    const nextCfgPath = 'C:/ComfyUI/books/' + nextSlug + '/config.json';
    const nextCfg = JSON.parse(fs.readFileSync(nextCfgPath, 'utf8').replace(/^\uFEFF/, ''));
    const front = (nextCfg.pages || []).find(function (p) { return p.page_key === 'page00'; });
    if (!front) throw new Error('next book config mangler page00');
    const base = items[0] ? items[0].json : {};
    items.push({ json: Object.assign({}, base, {
      page_key:          'page99_next',
      template_image:    front.template_image,
      mask_image:        front.mask_image,
      workflow_role:     'frontpage',
      workflow_api_file: (nextCfg.workflowApis && nextCfg.workflowApis.frontpage) ||
                         nextCfg.workflowApi || workflowFile,
      face_image:        faceFor(front.face_expression),
      patchNodes:        nextCfg.patchNodes || nextCfg.innerPatchNodes || patchNodes,
    })});
    console.log('[CONTINUE] page99_next lagt til fra ' + nextSlug + ' (' + front.template_image + ')');
  } catch (error) {
    // Et oppsalg skal aldri blokkere en betalt ordre.
    console.warn('[CONTINUE] hopper over neste-forside for ' + nextSlug + ': ' + error.message);
  }
}

return items;

const cfg = ($json && $json.config)
  ? $json
  : (($node['Page Loop'] && $node['Page Loop'].json)
      ? $node['Page Loop'].json
      : $json);

const config = cfg.config || (($node['Parse Config'] && $node['Parse Config'].json) ? $node['Parse Config'].json.config : undefined);
if (!config) throw new Error('No page config received for book ' + (cfg.book_slug || 'unknown'));

let raw = '';
if ($binary && $binary.data && typeof $binary.data.data === 'string') {
  raw = Buffer.from($binary.data.data, 'base64').toString('utf8');
} else if ($binary && $binary.data) {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} else if (typeof $json.data === 'string') {
  raw = $json.data;
}

if (!raw) {
  throw new Error('No Qwen headswap workflow data received for book ' + (cfg.book_slug || 'unknown') +
    ' workflow=' + (cfg.workflow_api_file || 'workflow_api.json'));
}

raw = raw.replace(/^\uFEFF/, '');

const prompt = JSON.parse(raw);
const configuredPatchNodes = cfg.patchNodes || config.patchNodes || config.innerPatchNodes || {};
const pn = Object.assign({}, configuredPatchNodes);

function hasInputs(nodeId) {
  return !!(nodeId && prompt[nodeId] && prompt[nodeId].inputs);
}

function hasInput(nodeId, inputName) {
  return hasInputs(nodeId) && Object.prototype.hasOwnProperty.call(prompt[nodeId].inputs, inputName);
}

function classType(nodeId) {
  return String((prompt[nodeId] && prompt[nodeId].class_type) || '');
}

function isRef(value, nodeId) {
  return Array.isArray(value) && String(value[0]) === String(nodeId);
}

function referenceScore(nodeId, classMatcher) {
  let score = 0;
  for (const node of Object.values(prompt)) {
    if (!node || !node.inputs) continue;
    if (classMatcher && !classMatcher(String(node.class_type || ''))) continue;
    for (const value of Object.values(node.inputs)) {
      if (isRef(value, nodeId)) score += 1;
    }
  }
  return score;
}

function loadImageCandidates() {
  return Object.entries(prompt)
    .filter(function(entry) {
      const nodeId = entry[0];
      const node = entry[1];
      return node && node.inputs && node.class_type === 'LoadImage' && hasInput(nodeId, 'image');
    })
    .map(function(entry) { return entry[0]; });
}

function detectOutputNode() {
  if (hasInput(pn.output, 'filename_prefix')) return pn.output;
  const candidates = Object.entries(prompt)
    .filter(function(entry) {
      const node = entry[1];
      return node && node.inputs && Object.prototype.hasOwnProperty.call(node.inputs, 'filename_prefix');
    })
    .map(function(entry) { return entry[0]; });
  const saveImage = candidates.find(function(nodeId) { return classType(nodeId) === 'SaveImage'; });
  return saveImage || candidates[0] || '';
}

function detectTemplateNode(excludeNodeId) {
  if (hasInput(pn.template, 'image')) return pn.template;
  const loaders = loadImageCandidates().filter(function(nodeId) { return String(nodeId) !== String(excludeNodeId || ''); });
  loaders.sort(function(a, b) {
    const templateConsumers = function(type) {
      return type === 'InpaintCropImproved' ||
        type === 'ImpactSimpleDetectorSEGS' ||
        type === 'SAMDetectorCombined' ||
        type.indexOf('GroundingDino') !== -1 ||
        type.indexOf('Segment') !== -1;
    };
    const aScore = referenceScore(a, templateConsumers) * 100 + referenceScore(a);
    const bScore = referenceScore(b, templateConsumers) * 100 + referenceScore(b);
    return bScore - aScore;
  });
  return loaders[0] || '';
}

function detectFaceNode(excludeNodeId) {
  if (hasInput(pn.face, 'image')) return pn.face;
  const loaders = loadImageCandidates().filter(function(nodeId) { return String(nodeId) !== String(excludeNodeId || ''); });
  const fluxFace = loaders.find(function(nodeId) {
    return referenceScore(nodeId, function(type) { return type === 'FluxKontextImageScale' || type.indexOf('FluxKontext') !== -1; }) > 0;
  });
  if (fluxFace) return fluxFace;
  loaders.sort(function(a, b) { return referenceScore(a) - referenceScore(b); });
  return loaders[0] || '';
}

pn.output = detectOutputNode();
pn.template = detectTemplateNode(pn.face);
pn.face = detectFaceNode(pn.template);

const requiredInputs = { template: 'image', face: 'image', output: 'filename_prefix' };
for (const key of Object.keys(requiredInputs)) {
  const nodeId = pn[key];
  const inputName = requiredInputs[key];
  if (!hasInput(nodeId, inputName)) {
    throw new Error((cfg.workflow_api_file || 'workflow_api.json') +
      ' could not auto-detect ' + key + ' patch node with input ' + inputName +
      ' for book ' + (cfg.book_slug || 'unknown') +
      '. Configured value was ' + (configuredPatchNodes[key] || 'missing'));
  }
  if (configuredPatchNodes[key] && String(configuredPatchNodes[key]) !== String(nodeId)) {
    console.log('Patch node auto-corrected for ' + (cfg.book_slug || 'unknown') +
      ': ' + key + ' ' + configuredPatchNodes[key] + ' -> ' + nodeId);
  }
}

prompt[pn.template].inputs.image = cfg.template_image;
prompt[pn.face].inputs.image = cfg.face_image;
prompt[pn.output].inputs.filename_prefix = cfg.output_dir + '/' + cfg.page_key;

// --- HEADMASK PATCH (safe & conditional) ---
// Only patches if the workflow has a dedicated mask loader. With the current
// auto-mask (SAM) workflow no such node exists, so this is a no-op.
function classTypeOf(id) { return String((prompt[id] && prompt[id].class_type) || ''); }
function detectMaskNode() {
  if (pn.mask && hasInput(pn.mask, 'image')) return pn.mask;
  for (const entry of Object.entries(prompt)) {
    const id = entry[0], node = entry[1];
    if (node && node.class_type === 'LoadImageMask' && hasInput(id, 'image')) return id;
  }
  for (const entry of Object.entries(prompt)) {
    const id = entry[0], node = entry[1];
    if (!node || node.class_type !== 'LoadImage' || !hasInput(id, 'image')) continue;
    if (String(id) === String(pn.template) || String(id) === String(pn.face)) continue;
    let refs = 0, maskRefs = 0;
    for (const other of Object.values(prompt)) {
      if (!other || !other.inputs) continue;
      for (const kv of Object.entries(other.inputs)) {
        if (Array.isArray(kv[1]) && String(kv[1][0]) === String(id)) { refs++; if (kv[0] === 'mask') maskRefs++; }
      }
    }
    if (refs > 0 && refs === maskRefs) return id;
  }
  return '';
}
pn.mask = detectMaskNode();
if (pn.mask && cfg.mask_image && prompt[pn.mask] && prompt[pn.mask].inputs) {
  prompt[pn.mask].inputs.image = cfg.mask_image;
}

for (const node of Object.values(prompt)) {
  if (node && node.inputs && Object.prototype.hasOwnProperty.call(node.inputs, 'scheduler') && node.inputs.scheduler === 'bong_tangent') {
    node.inputs.scheduler = 'ddim_uniform';
  }
}

const promptText = cfg.prompt_text || cfg.prompt || config.innerPrompt || '';
if (pn.prompt && promptText) {
  if (!prompt[pn.prompt] || !prompt[pn.prompt].inputs) {
    throw new Error((cfg.workflow_api_file || 'workflow_api.json') +
      ' is missing prompt patch node ' + pn.prompt +
      ' for book ' + (cfg.book_slug || 'unknown'));
  }
  if (Object.prototype.hasOwnProperty.call(prompt[pn.prompt].inputs, 'text')) {
    prompt[pn.prompt].inputs.text = promptText;
  } else if (Object.prototype.hasOwnProperty.call(prompt[pn.prompt].inputs, 'prompt')) {
    prompt[pn.prompt].inputs.prompt = promptText;
  }
}

return { json: {
  prompt: prompt,
  page_key: cfg.page_key,
  order_id: cfg.order_id,
  book_slug: cfg.book_slug,
  child_name: cfg.child_name,
  cover_type: cfg.cover_type,
  shipping: cfg.shipping,
  customer: cfg.customer,
  book_title: cfg.book_title,
  language: cfg.language || 'nb',
  site_language: cfg.site_language || 'no',
  market: cfg.market || 'no',
  script_language: cfg.script_language || 'nb',
  config: config,
  orderPath: cfg.orderPath,
  workflow_role: cfg.workflow_role || 'page',
  workflow_api_file: cfg.workflow_api_file || 'workflow_api.json',
  patchNodes: pn,
  mask_image: cfg.mask_image || '',
  output_dir: cfg.output_dir || '',
  pageOutputDir: cfg.pageOutputDir || '',
  comfyLock: cfg.comfyLock || null,
} };

const http = require('http');

if (!$json.prompt || typeof $json.prompt !== 'object') {
  throw new Error('HTTP Request ComfyUI missing prompt object');
}

const payload = JSON.stringify({ prompt: $json.prompt });
const timeoutMs = 180000;

const response = await new Promise((resolve, reject) => {
  const req = http.request({
    hostname: '127.0.0.1',
    port: 8188,
    path: '/prompt',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(payload),
      'Connection': 'close',
    },
    timeout: timeoutMs,
  }, (res) => {
    let body = '';
    res.setEncoding('utf8');
    res.on('data', chunk => { body += chunk; });
    res.on('end', () => {
      let parsed = {};
      if (body && body.trim()) {
        try { parsed = JSON.parse(body); }
        catch (error) { return reject(new Error('Invalid ComfyUI /prompt JSON: ' + error.message + ' body=' + body.slice(0, 500))); }
      }
      if (res.statusCode < 200 || res.statusCode >= 300) {
        return reject(new Error('ComfyUI /prompt HTTP ' + res.statusCode + ': ' + body.slice(0, 1500)));
      }
      resolve(parsed);
    });
  });
  req.on('timeout', () => req.destroy(new Error('ComfyUI /prompt timed out after ' + timeoutMs + 'ms')));
  req.on('error', reject);
  req.write(payload);
  req.end();
});

