    createdAt: now,
    executionId,
    order_id: $json.order_id || '',
    book_slug: $json.book_slug || '',
    page_key: $json.page_key || '',
    pageOutputDir: $json.pageOutputDir || '',
  };
  const fd = fs.openSync(lockPath, 'wx');
  try { fs.writeFileSync(fd, JSON.stringify(lock, null, 2), 'utf8'); }
  finally { fs.closeSync(fd); }
  return lock;
}

try {
  const lock = tryCreate();
  return { json: Object.assign({}, $json, { lockAcquired: true, lockWaitReason: '', comfyLock: Object.assign({ path: lockPath }, lock) }) };
} catch (error) {
  if (error && error.code !== 'EEXIST') throw error;
}

const existing = readLock();
const samePage = existing &&
  String(existing.order_id || '') === String($json.order_id || '') &&
  String(existing.book_slug || '') === String($json.book_slug || '') &&
  String(existing.page_key || '') === String($json.page_key || '');
if (samePage && pageExists($json.pageOutputDir || existing.pageOutputDir, $json.page_key || existing.page_key)) {
  try { fs.unlinkSync(lockPath); } catch (error) {}
  return {
    json: Object.assign({}, $json, {
      lockAcquired: false,
      lockWaitReason: 'released matching completed page lock; rechecking output',
      comfyLock: existing ? Object.assign({ path: lockPath }, existing) : { path: lockPath },
    }),
  };
}

if (lockIsStale(existing)) {
  try { fs.unlinkSync(lockPath); } catch (error) {}
  try {
    const lock = tryCreate();
    return { json: Object.assign({}, $json, { lockAcquired: true, lockWaitReason: 'replaced stale lock', comfyLock: Object.assign({ path: lockPath }, lock) }) };
  } catch (error) {
    if (error && error.code !== 'EEXIST') throw error;
  }
}

// Laasen tilhoerer en annen kjoering. Send ALDRI dens felter videre i
// comfyLock: pageOutputDir ville sendt Check Page Output inn i den andre
// ordrens mappe, og tokenen ville latt Release Comfy Lock slette en laas
// vi ikke eier. Kun diagnostikk herfra.
return {
  json: Object.assign({}, $json, {
    lockAcquired: false,
    lockWaitReason: existing
      ? ('Comfy busy with order ' + (existing.order_id || '?') + ' ' + (existing.page_key || '?'))
      : 'Comfy lock exists',
    lockOwner: existing
      ? { order_id: existing.order_id || '', book_slug: existing.book_slug || '',
          page_key: existing.page_key || '', executionId: existing.executionId || '' }
      : null,
    comfyLock: { path: lockPath },
  }),
};

const intervalSec = Number($json.lockWaitIntervalSec ?? 10);
const boundedSec = Math.max(1, Math.min(intervalSec, 60));
await new Promise(resolve => setTimeout(resolve, boundedSec * 1000));
return { json: Object.assign({}, $json, { lockWaitIntervalSec: boundedSec }) };

const fs = require('fs');
const path = require('path');
const lock = $json.comfyLock || {};
const lockPath = lock.path || 'C:/ComfyUI/.dreampage-comfy.lock';
let released = false;
let lockReleaseNote = '';

function pageExists(dir, pageKey) {
  if (!dir || !pageKey || !fs.existsSync(dir)) return false;
  return fs.readdirSync(dir).some(name => {
    if (!name.startsWith(pageKey + '_') || !/\.(png|jpg|jpeg|webp)$/i.test(name)) return false;
    try { return fs.statSync(path.join(dir, name)).size > 0; }
    catch (error) { return false; }
  });
}

if (fs.existsSync(lockPath)) {
  try {
    const current = JSON.parse(fs.readFileSync(lockPath, 'utf8'));
    const selfId = (typeof $execution !== 'undefined' && $execution.id) ? String($execution.id) : 'unknown';
    const ownedByUs = current && String(current.executionId || '') === selfId;
    const tokenMatches = ownedByUs && lock.token && current.token === lock.token;
    const samePage = current &&
      String(current.order_id || '') === String($json.order_id || '') &&
      String(current.book_slug || '') === String($json.book_slug || '') &&
      String(current.page_key || '') === String($json.page_key || '');
    const completedPageExists = pageExists($json.pageOutputDir || current.pageOutputDir || lock.pageOutputDir, $json.page_key || current.page_key);

    // ownedByUs alene holder: paa feilgrenen fra HTTP Request ComfyUI er
    // det ikke garantert at $json.comfyLock (og dermed tokenen) overlever,
    // men en laas VI har laget er alltid trygg aa fjerne.
    if (tokenMatches || ownedByUs || (samePage && completedPageExists)) {
      fs.unlinkSync(lockPath);
      released = true;
      if (!tokenMatches) lockReleaseNote = 'released matching completed page lock without token match';
    } else {
      lockReleaseNote = 'lock token did not match current owner';
    }
  } catch (error) {
    lockReleaseNote = error && error.message ? error.message : String(error);
  }
}

return { json: Object.assign({}, $json, { lockReleased: released, lockReleaseNote }) };

